// ─────────────────────────────────────────────────────────────────────────────
// SEARCH FUNCTION
// Returns up to `limit` results ranked by relevance.
// title match > keyword exact > keyword partial > description
// ─────────────────────────────────────────────────────────────────────────────

export function searchSite(query, limit = 12) {
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const terms = q.split(/\s+/);

  const scored = SEARCH_INDEX.map((item) => {
    const titleL = item.title.toLowerCase();
    const descL  = item.description.toLowerCase();
    const kwL    = item.keywords;
    let score = 0;

    for (const term of terms) {
      // Title — highest weight
      if (titleL === term)                          score += 100;
      else if (titleL.startsWith(term))             score += 60;
      else if (titleL.includes(term))               score += 40;

      // Section breadcrumb
      if (item.section.toLowerCase().includes(term)) score += 12;

      // Keywords — exact then partial
      if (kwL.some((k) => k === term))              score += 35;
      else if (kwL.some((k) => k.startsWith(term))) score += 20;
      else if (kwL.some((k) => k.includes(term)))   score += 12;

      // Description
      if (descL.includes(term))                     score += 6;
    }

    return { ...item, score };
  });

  return scored
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

